                if (regs->beg[n] >= 0 && regs->beg[n] < regs->end[n] && regs->end[n] <= string_len) {
                    smart_str_appendl(pbuf, string + regs->beg[n], regs->end[n] - regs->beg[n]);
                }
                p += 2;
                i += 2;
            } else {
                smart_str_appendl(pbuf, p, fwd);
                p += fwd;
                i += fwd;
            }
        }
    }
    // ... (остальное без изменений, но в цикле подпаттернов добавить проверки)
    for (i = 0; i < regs->num_regs; i++) {
        if (regs->beg[i] >= 0 && regs->end[i] >= regs->beg[i] && regs->end[i] <= string_len) {
            add_next_index_stringl(subpats, string + regs->beg[i], regs->end[i] - regs->beg[i], 1);
        } else {
            add_next_index_stringl(subpats, "", 0, 1);
        }
    }
    // ... (конец)
}

